#ifndef WS_IO_H
#define WS_IO_H

#include <cstdint>
#include <vector>
#include <atomic>
#include <iostream>
#include <system_error>
#include "util.h"
#include "containers/buffer.h"

namespace ws::io {

class IReader {
public:
  virtual ~IReader() = default;
  virtual std::size_t ReadFrom(Buffer& buf) = 0;
};

class IWriter {
public:
  virtual ~IWriter() = default;
  virtual std::size_t WriteTo(Buffer& buf) = 0;
};

class IReadWriter : public IReader, public IWriter {};

class Null : public IReadWriter {
public:
  std::size_t WriteTo(Buffer& buf) noexcept override;
  std::size_t ReadFrom(Buffer& buf) noexcept override;
};

class StringStream : public IReadWriter {
private:
  std::istream& read_;
  std::ostream& write_;
public:
  explicit StringStream(std::istream& read, std::ostream& write) noexcept;
  std::size_t WriteTo(Buffer& buf) noexcept override;
  std::size_t ReadFrom(Buffer& buf) noexcept override;
};

class FileDescriptor : public IReadWriter {
private:
  ws::FileDescriptor read_;
  ws::FileDescriptor write_;
public:
  explicit FileDescriptor(ws::FileDescriptor read, ws::FileDescriptor write) noexcept;
  std::size_t WriteTo(Buffer& buf) override;
  std::size_t ReadFrom(Buffer& buf) override;
};

}

#endif // WS_IO_H

#include "io.h"

#include <cstring>
#include <unistd.h>

namespace ws::io {

std::size_t Null::WriteTo(Buffer& buf) noexcept {
  const std::size_t size = buf.WritableSize();
  buf.Consume(size);
  return size;
}

std::size_t Null::ReadFrom(Buffer& buf) noexcept {
  return buf.RetrieveAll();
}

StringStream::StringStream(std::istream& read, std::ostream& write) noexcept : read_(read), write_(write) {}

std::size_t StringStream::WriteTo(Buffer& buf) noexcept {
  std::string temp;
  std::getline(read_, temp);
  const std::size_t written = buf.Append(temp);
  return written;
}

std::size_t StringStream::ReadFrom(Buffer& buf) noexcept {
  std::string data = buf.RetrieveAllToString();
  write_ << data;
  return data.length();
}

FileDescriptor::FileDescriptor(ws::FileDescriptor read, ws::FileDescriptor write) noexcept : read_(read), write_(write) {}

std::size_t FileDescriptor::WriteTo(Buffer& buf) {
  const std::vector<struct iovec> iovs = { {buf.Data(), buf.WritableSize()} };
  const ssize_t written = ::writev(write_, iovs.data(), static_cast<int>(iovs.size()));
  if (written == -1) {
    throw std::system_error(errno, std::system_category());
  }
  buf.Consume(static_cast<std::size_t>(written));
  return static_cast<std::size_t>(written);
}

std::size_t FileDescriptor::ReadFrom(Buffer& buf) {
  const std::vector<struct iovec> iovs = { {buf.Data(), buf.AvailableSize()} };
  const ssize_t read_bytes = ::readv(read_, iovs.data(), static_cast<int>(iovs.size()));
  if (read_bytes == -1) {
    throw std::system_error(errno, std::system_category());
  }
  buf.Append(static_cast<std::size_t>(read_bytes));
  return static_cast<std::size_t>(read_bytes);
}

}
